 document.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag))return;if(e.key==='Escape'){state.drawing=false;state.polyPoints=[];layer('previewLayer').replaceChildren();hideModal('textModal');selectTool('select');}else if(e.key==='Enter'&&state.activeTool==='polyline')finishPolyline();else if(e.key==='Delete'||e.key==='Backspace')deleteSelected();else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();}else if(e.key==='F8'){state.ortho=!state.ortho;if($('orthoToggle'))$('orthoToggle').checked=state.ortho;if($('orthoBtn'))$('orthoBtn').classList.toggle('active',state.ortho);updateStatus();}else if(state.selected.length&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const n=e.shiftKey?10:1;moveSelected(e.key==='ArrowLeft'?-n:e.key==='ArrowRight'?n:0,e.key==='ArrowUp'?-n:e.key==='ArrowDown'?n:0);}});
