function renderPolylinePreview(cursor){const p=layer('previewLayer');p.replaceChildren();if(!state.polyPoints.length)return;const pts=[...state.polyPoints,...(cursor?[cursor]:[])];p.append(make('polyline',{points:pts.map(x=>`${x.x},${x.y}`).join(' '),fill:'none',stroke:'#168eae','stroke-width':.35,'stroke-dasharray':'2 1'}));}
function finishPolyline(){if(state.polyPoints.length<2){state.polyPoints=[];layer('previewLayer').replaceChildren();return;}addObject({type:'polyline',points:clone(state.polyPoints),stroke:$('drawingColor')?.value||'#20252b',strokeWidth:num($('drawingLineWidth')?.value,.5),dash:$('drawingDash')?.value||undefined});state.polyPoints=[];layer('previewLayer').replaceChildren();}
function nearestObject(p){let best=null,dist=Infinity;for(const o of state.objects){let d=1e9;if(o.type==='line'||o.type==='arrowLine'){const dx=o.x2-o.x1,dy=o.y2-o.y1,t=Math.max(0,Math.min(1,((p.x-o.x1)*dx+(p.y-o.y1)*dy)/(dx*dx+dy*dy||1)));d=Math.hypot(p.x-(o.x1+t*dx),p.y-(o.y1+t*dy));}else if(o.type==='circle')d=Math.abs(Math.hypot(p.x-o.cx,p.y-o.cy)-o.r);else if(o.type==='rect')d=Math.min(Math.hypot(p.x-o.x,p.y-o.y),Math.hypot(p.x-o.x-o.w,p.y-o.y),Math.hypot(p.x-o.x,p.y-o.y-o.h),Math.hypot(p.x-o.x-o.w,p.y-o.y-o.h));else if(o.x!==undefined)d=Math.hypot(p.x-o.x,p.y-o.y);if(d<dist){dist=d;best=o;}}return dist<5?best:null;}
function moveObjectLive(id,before,dx,dy){const o=state.objects.find(x=>x.id===id);if(!o||!before)return;Object.assign(o,clone(before));if(o.x!==undefined)o.x+=dx;if(o.y!==undefined)o.y+=dy;if(o.cx!==undefined)o.cx+=dx;if(o.cy!==undefined)o.cy+=dy;if(o.x1!==undefined){o.x1+=dx;o.x2+=dx;o.y1+=dy;o.y2+=dy;}if(o.points)o.points=o.points.map(p=>({x:p.x+dx,y:p.y+dy}));render();}
function snapshotBeforeAlreadyMoved(id){const o=state.objects.find(x=>x.id===id);if(!o)return;const before=state.dragBefore;const after=clone(o);const old=clone(state.objects);state.undo.push(JSON.stringify({objects:old.map(x=>x.id===id?before:x),format:state.format,width:state.width,height:state.height,template:state.template,name:state.name}));state.redo=[];updateUndoButtons();}
function init(){
  // The shipped HTML shell was authored for a missing engine; initialise it to a working A3 landscape CAD sheet.
  if(!svg||!area){console.error('CAD startup: #sheetSvg or #drawingArea missing');return;}
  if($('drawingColor')===null){const color=document.createElement('input');color.type='color';color.id='drawingColor';color.value='#20252b';color.hidden=true;document.body.append(color);}
  if($('drawingDash')===null){const dash=document.createElement('input');dash.id='drawingDash';dash.hidden=true;document.body.append(dash);}
  const old=$('paperFormat');if(old)old.value='A3L';state.format='A3L';[state.width,state.height]=FORMATS.A3L;pageAttrs();state.grid=false;state.snap=false;state.ortho=false;applyTemplate();fit();updateMeta();initNewDocDialog();setupEvents();render();updateSelectionPanel();setSaved(true);selectTool('select');status(`Готово · ${state.name} · ${formatName()}`);
  // Restore autosave only when explicitly requested; never unexpectedly replace a fresh document.
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
